    1	// Package bank models accounts with per-account locks.
    2	package bank
    3	
    4	import (
    5		"errors"
    6		"sync"
    7	)
    8	
    9	var (
   10		ErrInsufficient = errors.New("bank: insufficient funds")
   11		ErrSameAccount  = errors.New("bank: same account")
   12		ErrBadAmount    = errors.New("bank: amount must be positive")
   13		ErrNoAccount    = errors.New("bank: no such account")
   14	)
   15	
   16	// Account holds a balance in cents.
   17	type Account struct {
   18		ID      int
   19		mu      sync.Mutex
   20		balance int64
   21	}
   22	
   23	// Balance returns the current balance.
   24	func (a *Account) Balance() int64 {
   25		a.mu.Lock()
   26		defer a.mu.Unlock()
   27		return a.balance
   28	}
   29	
   30	// Bank is a set of accounts.
   31	type Bank struct {
   32		accounts map[int]*Account
   33	}
   34	
   35	// New creates a bank with the given opening balances, IDs 0..n-1.
   36	func New(balances ...int64) *Bank {
   37		b := &Bank{accounts: map[int]*Account{}}
   38		for i, bal := range balances {
   39			b.accounts[i] = &Account{ID: i, balance: bal}
   40		}
   41		return b
   42	}
   43	
   44	// Account returns an account by ID.
   45	func (b *Bank) Account(id int) (*Account, error) {
   46		a, ok := b.accounts[id]
   47		if !ok {
   48			return nil, ErrNoAccount
   49		}
   50		return a, nil
   51	}
   52	
   53	// Transfer moves amount from one account to another atomically.
   54	func (b *Bank) Transfer(from, to int, amount int64) error {
   55		if amount <= 0 {
   56			return ErrBadAmount
   57		}
   58		if from == to {
   59			return ErrSameAccount
   60		}
   61		src, err := b.Account(from)
   62		if err != nil {
   63			return err
   64		}
   65		dst, err := b.Account(to)
   66		if err != nil {
   67			return err
   68		}
   69		src.mu.Lock()
   70		defer src.mu.Unlock()
   71		dst.mu.Lock()
   72		defer dst.mu.Unlock()
   73		if src.balance < amount {
   74			return ErrInsufficient
   75		}
   76		src.balance -= amount
   77		dst.balance += amount
   78		return nil
   79	}
   80	
   81	// Total sums all balances.
   82	func (b *Bank) Total() int64 {
   83		var t int64
   84		for _, a := range b.accounts {
   85			t += a.Balance()
   86		}
   87		return t
   88	}

